    ) -> HashMap<i64, Project> {
        network_projects
            .into_iter()
            .map(|project| {
                (
                    project.id,
                    Project {
                        id: project.id,
                        name: project.name,
                        workspace_id: project.workspace_id,
                        client: clients.get(&project.client_id.unwrap_or(-1)).cloned(),
                        is_private: project.is_private,
                        active: project.active,
                        at: project.at,
                        created_at: project.created_at,
