use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;
use std::io::{self, Write};

const FIFTEEN_MINUTES: i64 = 15 * 60;
const MINIMUM_BILLING_INCREMENT: i64 = 30 * 60;

pub struct InvoiceCommand;

fn billed_duration(duration: i64) -> i64 {
    let rounded = ((duration + FIFTEEN_MINUTES - 1) / FIFTEEN_MINUTES) * FIFTEEN_MINUTES;
    rounded.max(MINIMUM_BILLING_INCREMENT)
}

/// Format billable, stopped entries as project totals in invoice order.
pub fn format_invoice(entries: &[TimeEntry]) -> String {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries {
        if entry.billable && entry.stop.is_some() && !entry.is_running() && entry.duration >= 0 {
            *totals
                .entry(
                    entry
                        .project
                        .as_ref()
                        .map_or_else(|| "No Project".to_string(), |project| project.name.clone()),
                )
                .or_default() += billed_duration(entry.duration);
        }
    }

    let mut totals = totals.into_iter().collect::<Vec<_>>();
    totals.sort_by(|(left_name, left_total), (right_name, right_total)| {
        right_total
            .cmp(left_total)
            .then_with(|| left_name.cmp(right_name))
    });

    if totals.is_empty() {
        return "(no data)\n".to_string();
    }

    let total = totals.iter().map(|(_, seconds)| seconds).sum::<i64>();
    let mut output = totals
        .into_iter()
        .map(|(project, seconds)| format!("{seconds}s  {project}"))
        .collect::<Vec<_>>();
    output.push(format!("{total}s  Total"));
    output.join("\n") + "\n"
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let mut stdout = io::BufWriter::new(io::stdout());
        write!(stdout, "{}", format_invoice(&entries)).expect("failed to print invoice");
        Ok(())
    }
}

